	/**
	 * Method to retrieve the GoodsReceipt via GoodsReceiptFetchOneSummary
	 * @param 	summary GoodsReceiptFetchOneSummary
	 * @return 	GoodsReceiptFetchOneResponse
	 */
	public GoodsReceipt getGoodsReceipt( GoodsReceiptFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "GoodsReceiptFetchOneSummary arg cannot be null" );

		GoodsReceipt entity = null;
		UUID id = summary.getGoodsReceiptId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a GoodsReceipt using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


